import{z as s,x as B,o as E,c as A,q as r,j as l,D as i,d as n,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"流动性条件","description":"","frontmatter":{"title":"流动性条件","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-liquidity-conditions.md","filePath":"quant/mac-liquidity-conditions.md","lastUpdated":1791063341000}'),u={name:"quant/mac-liquidity-conditions.md"};function p(m,a,f,D,g,h){const t=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=r('<h1 id="流动性条件" tabindex="-1">流动性条件 <a class="header-anchor" href="#流动性条件" aria-label="Permalink to &quot;流动性条件&quot;">​</a></h1><div class="epigraph"><p>流动性不是一种东西：央行给的是准备金，市场给的是深度，经纪人给的是保证金——三条链断了哪一条，资产的表现都不一样。</p><footer>—— 据 Brunnermeier &amp; Pedersen, Review of Financial Studies, 2009 与 Nagel, Review of Financial Studies, 2012 整理</footer></div><p><a href="/quant/mac-growth-inflation-quadrant">上一课</a>用增长与通胀两轴给四个象限配上相对赢家。但 2008 年与 2020 年的转折先发生在资金面：增长-通胀刻得动中期趋势，刻不动保证金螺旋驱动的快下跌。本课把流动性从背景提为第三根轴，分清三条不同口径的「流动性」，并给出监控与风险开关的用法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>象限表假设资产可以按赢家顺序平稳换仓；资金面收紧时这个假设先破：全市场保证金抬升迫使同向去杠杆，跨资产相关性塌向 1，名义分散失效。更麻烦的是「流动性」被当成一个词用，其实至少三条链：央行与银行体系的准备金（资金可得性）、市场流动性（价差与深度）、funding liquidity（杠杆投资者的保证金与融资）。混用三条链会错判两次：看到央行扩表就断定资产必涨——第一条链宽松不等于第三条链不紧；或把市场价差走阔当成央行收紧。缺口是分链度量、合成条件指数，并明确它进风险预算而不是收益预测。</p><p><span class="marginnote">「funding liquidity」翻译成白话：你还能不能借到继续持仓所需的钱、要追加多少保证金。它与「市场流动性」（想卖时有没有人接盘）是两回事——完全可以出现没有人卖、但人人都在被追缴保证金的局面。</span></p><h3 id="三条链的度量" tabindex="-1">三条链的度量 <a class="header-anchor" href="#三条链的度量" aria-label="Permalink to &quot;三条链的度量&quot;">​</a></h3><p>央行与银行链看准备金余额、资产负债表净变动、政策利率在走廊的位置，信用侧加票据与 OIS 利差。市场链看国债与期货的买卖价差、深度、Amihud 价格冲击系数，加期现基差。funding 链看保证金率、回购折扣与互换基差。各链标准化、滞后对齐后合成条件指数。</p><p><span class="marginnote">Brunnermeier–Pedersen 的 margin 螺旋：funding 收紧迫使降杠杆，降杠杆压市场深度，深度恶化再抬保证金，两条链相互增强。Nagel 用套利误差的走阔度量这条链：资金最紧时「免费午餐」反而最大，因为想吃它的人借不到钱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地分两步。第一步建指数：三链各选两三个指标，标准化后按风险预算等权——不按样本内解释力加权，避免挑权重；价格侧日度更新，宏观侧月度校准。第二步定用途：条件指数只做风险开关——紧缩态压总风险预算、放宽再平衡节奏，不直接当方向信号。与<a href="/quant/vol-targeting">波动目标</a>分工：vol targeting 盯已实现波动，流动性指数盯「去杠杆能不能成交」这个执行条件；波动还没起而 funding 先紧时，后者先触发减仓。</p><p><span class="marginnote">「风险开关不是方向信号」的直觉类比：烟雾报警器不会告诉你火从哪来、要不要搬家，它只让你先放下手里的活去查看。流动性指数报紧时，动作是压仓位、给执行留余量，不是预测「明天涨还是跌」。</span></p>',12)),(E(),l(d,null,{default:i(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CB%5B%22%E5%A4%AE%E8%A1%8C%E4%B8%8E%E9%93%B6%E8%A1%8C%E9%93%BE%22%5D%20--%3E%20IX%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E6%9D%A1%E4%BB%B6%E6%8C%87%E6%95%B0%22%5D%0A%20%20MK%5B%22%E5%B8%82%E5%9C%BA%E6%B7%B1%E5%BA%A6%E9%93%BE%22%5D%20--%3E%20IX%0A%20%20FU%5B%22funding%20%E9%93%BE%22%5D%20--%3E%20IX%0A%20%20IX%20--%3E%20RB%5B%22%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E5%BC%80%E5%85%B3%22%5D%0A%20%20IX%20--%3E%20SIG%5B%22%E4%B8%8E%E6%B3%A2%E5%8A%A8%E7%9B%AE%E6%A0%87%E4%BA%92%E6%A3%80%22%5D%0A%20%20FU%20--%3E%20SP%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E8%9E%BA%E6%97%8B%E7%9B%91%E6%8E%A7%22%5D%0A%20%20SP%20--%3E%20MK%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"为什么流动性是第三根轴：跨资产策略的收益不只来自状态判断，还来自能否按判断的价格调仓。funding 紧时，套利与 carry 仓位的保证金上升，浮亏仓位被迫先平，抛压集中在最需要流动性的时点出现，市场链随之恶化。2008 年 TED-OIS 利差一度超过 300 个基点、2020 年 3 月最安全的美债现货价差也走阔，是同一机制的两个标本。策略含义：象限换格的最差执行时点恰恰是条件指数报紧的时点，风险预算必须在信号之前就给执行留余量——把换仓拆片、预留冲击成本，而不是假设中间价成交。",-1)),a[5]||(a[5]=e("h2",{id:"边界",tabindex:"-1"},[n("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[6]||(a[6]=e("p",null,"三条链不是机械传导：央行扩表不等于银行放贷（乘数内生），准备金充裕时市场深度仍可以极差。合成指数的权重有任意性，换指标集结论可能翻转，要报告稳健性而不是只报一条线。「流动性驱动的下跌」多数事后才分得清，实时只承认「条件紧」这个事实并按风险开关反应。也不要把缩表机械映射为下跌：第一链收缩的定价影响，取决于它与增长、通胀意外的相对大小——流动性只是轴，不是全部的地图。",-1)),(E(),l(d,null,{default:i(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22funding%20%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20MG%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E6%8A%AC%E5%8D%87%22%5D%0A%20%20MG%20--%3E%20DL%5B%22%E8%A2%AB%E8%BF%AB%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20DL%20--%3E%20SP%5B%22%E6%8A%9B%E5%8E%8B%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%90%8C%E4%B8%80%E6%97%B6%E7%82%B9%22%5D%0A%20%20SP%20--%3E%20DP%5B%22%E5%B8%82%E5%9C%BA%E6%B7%B1%E5%BA%A6%E6%81%B6%E5%8C%96%22%5D%0A%20%20DP%20--%3E%20MG%0A%20%20DL%20--%3E%20CR%5B%22%E8%B7%A8%E8%B5%84%E4%BA%A7%E7%9B%B8%E5%85%B3%E6%80%A7%E5%A1%8C%E5%90%91%201%22%5D%0A%20%20CR%20--%3E%20ND%5B%22%E5%90%8D%E4%B9%89%E5%88%86%E6%95%A3%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：看到央行扩表的新闻就买资产。扩表给的是银行体系的准备金（第一条链），若杠杆投资者的保证金仍在收紧（第三条链），资产照样跌——2020 年 3 月美联储已开始投放流动性，市场仍先暴跌了约两周。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>「流动性」至少三条链：央行准备金、市场深度、funding 保证金；混用必然错判。</li><li>条件指数按风险预算等权合成，用途是风险开关与执行余量，不是方向信号。</li><li>保证金螺旋让去杠杆集中在最需要流动性的时候；与 vol targeting 互检。</li><li>扩表不等于放贷、缩表不机械等于下跌；换指标集要报稳健性。</li><li>出处：Brunnermeier &amp; Pedersen, RFS, 2009；Nagel, RFS, 2012；波动目标口径见<a href="/quant/vol-targeting">波动目标</a>。</li></ul>',3))])}const P=s(u,[["render",p]]);export{q as __pageData,P as default};
